SELECT "line_id", "request_number", "item", "quantity", "way", "customer", "customer_email", "obligation_id", "due", "obligation_state", "qty_ok", "qty_bad", "last_received", "days_open", "reminders", "route", 'nothing returned after ' || CAST(:inbound_reminder AS VARCHAR) || ' days' AS "verdict_reason"
FROM (SELECT "t26"."line_id", "t26"."request_number", "t26"."item", "t26"."quantity", "t26"."way", "t26"."customer", "t26"."customer_email", "t26"."obligation_id", "t26"."due", "t26"."obligation_state", "t26"."qty_ok", "t26"."qty_bad", "t26"."last_received", "t26"."days_open", "t31"."reminders", CASE WHEN "t26"."qty_ok" >= "t26"."quantity" THEN 'complete' WHEN "t26"."qty_bad" > 0 OR "t26"."qty_ok" > 0 AND "t26"."qty_ok" < "t26"."quantity" THEN 'damaged' WHEN "t26"."days_open" > :inbound_close THEN 'expired' WHEN "t26"."days_open" > :inbound_reminder AND "t31"."reminders" = 0 THEN 'remind' ELSE NULL END AS "route"
        FROM (SELECT "t10"."line_id", "t10"."request_number", "t10"."item", "t10"."quantity", "t10"."way", "t10"."customer", "t10"."customer_email", "t10"."obligation_id", "t10"."due", "t10"."obligation_state", "t10"."qty_ok", "t10"."qty_bad", "t10"."last_received", "t25"."days_open"
                FROM (SELECT "t2"."line_id", "t2"."request_number", "t2"."item", "t2"."quantity", "t2"."way", "t2"."customer", "t2"."customer_email", "t2"."obligation_id", "t2"."due", "t2"."obligation_state", "t9"."qty_ok", "t9"."qty_bad", "t9"."last_received"
                        FROM (SELECT "t0"."line_id", "t0"."request_number", "t0"."item", "t0"."quantity", "t0"."way", "t0"."customer0" AS "customer", "t0"."email" AS "customer_email", "obligation"."id" AS "obligation_id", "obligation"."due", "obligation"."state" AS "obligation_state"
                                FROM (SELECT "t"."line_id", "t"."request_number", "t"."line_no", "t"."item", "t"."quantity", "t"."unit_price", "t"."reason", "t"."requested_resolution", "t"."requested_variant", "t"."state", "t"."way", "t"."customer", "t"."customer0", "t"."order_number", "t"."channel", "t"."requested_date", "t"."state0", "customer"."customer_id", "customer"."addr", "customer"."cdemo", "customer"."hdemo", "customer"."birth_year", "customer"."center", "customer"."email"
                                        FROM (SELECT "return_request_line"."line_id", "return_request_line"."request_number", "return_request_line"."line_no", "return_request_line"."item", "return_request_line"."quantity", "return_request_line"."unit_price", "return_request_line"."reason", "return_request_line"."requested_resolution", "return_request_line"."requested_variant", "return_request_line"."state", "return_request_line"."way", "return_request_line"."customer", "return_request"."customer" AS "customer0", "return_request"."order_number", "return_request"."channel", "return_request"."requested_date", "return_request"."state" AS "state0"
                                                FROM "return_request_line"
                                                    INNER JOIN "return_request" ON "return_request_line"."request_number" = "return_request"."request_number") AS "t"
                                            LEFT JOIN "customer" ON "t"."customer" = "customer"."sk") AS "t0"
                                    INNER JOIN "obligation" ON "obligation"."entity" = 'return_request_line' AND "obligation"."key" = CAST("t0"."line_id" AS VARCHAR) AND "obligation"."kind" = 'inbound' AND "obligation"."state" IN ('open', 'overdue', 'reopened')
                                WHERE "t0"."state" = 'awaiting_goods') AS "t2"
                            LEFT JOIN (SELECT "t6"."line_id", COALESCE(SUM(CASE WHEN "return_receipt"."condition" = 'ok' THEN "return_receipt"."quantity" ELSE 0 END), 0) AS "qty_ok", COALESCE(SUM(CASE WHEN "return_receipt"."condition" <> 'ok' THEN "return_receipt"."quantity" ELSE 0 END), 0) AS "qty_bad", MAX("return_receipt"."received_date") AS "last_received"
                                FROM (SELECT "t4"."line_id", "t4"."request_number", "t4"."item", "t4"."quantity", "t4"."way", "t4"."customer0" AS "customer", "t4"."email" AS "customer_email", "obligation0"."id" AS "obligation_id", "obligation0"."due", "obligation0"."state" AS "obligation_state"
                                        FROM (SELECT "t3"."line_id", "t3"."request_number", "t3"."line_no", "t3"."item", "t3"."quantity", "t3"."unit_price", "t3"."reason", "t3"."requested_resolution", "t3"."requested_variant", "t3"."state", "t3"."way", "t3"."customer", "t3"."customer0", "t3"."order_number", "t3"."channel", "t3"."requested_date", "t3"."state0", "customer0"."customer_id", "customer0"."addr", "customer0"."cdemo", "customer0"."hdemo", "customer0"."birth_year", "customer0"."center", "customer0"."email"
                                                FROM (SELECT "return_request_line0"."line_id", "return_request_line0"."request_number", "return_request_line0"."line_no", "return_request_line0"."item", "return_request_line0"."quantity", "return_request_line0"."unit_price", "return_request_line0"."reason", "return_request_line0"."requested_resolution", "return_request_line0"."requested_variant", "return_request_line0"."state", "return_request_line0"."way", "return_request_line0"."customer", "return_request0"."customer" AS "customer0", "return_request0"."order_number", "return_request0"."channel", "return_request0"."requested_date", "return_request0"."state" AS "state0"
                                                        FROM "return_request_line" AS "return_request_line0"
                                                            INNER JOIN "return_request" AS "return_request0" ON "return_request_line0"."request_number" = "return_request0"."request_number") AS "t3"
                                                    LEFT JOIN "customer" AS "customer0" ON "t3"."customer" = "customer0"."sk") AS "t4"
                                            INNER JOIN "obligation" AS "obligation0" ON "obligation0"."entity" = 'return_request_line' AND "obligation0"."key" = CAST("t4"."line_id" AS VARCHAR) AND "obligation0"."kind" = 'inbound' AND "obligation0"."state" IN ('open', 'overdue', 'reopened')
                                        WHERE "t4"."state" = 'awaiting_goods') AS "t6"
                                    LEFT JOIN "return_receipt" ON "t6"."line_id" = "return_receipt"."line_id"
                                GROUP BY "t6"."line_id") AS "t9" ON "t2"."line_id" = "t9"."line_id") AS "t10"
                    LEFT JOIN (SELECT "t15"."line_id", CASE WHEN "t15"."_ttrp_a_n17_0" IS NULL THEN NULL ELSE COALESCE("t24"."_ttrp_n_n17_0", 0) END AS "days_open"
                        FROM (SELECT "t14"."line_id", "t14"."request_number", "t14"."item", "t14"."quantity", "t14"."way", "t14"."customer", "t14"."customer_email", "t14"."obligation_id", "t14"."due", "t14"."obligation_state", "obligation2"."recipe", "obligation2"."run", "obligation2"."entity", "obligation2"."key", "obligation2"."kind", "obligation2"."due" AS "due0", "obligation2"."state", "obligation2"."fulfilled_by", "obligation2"."fulfilled_at", "obligation2"."created_at", "obligation2"."created_at" AS "_ttrp_a_n17_0"
                                FROM (SELECT "t12"."line_id", "t12"."request_number", "t12"."item", "t12"."quantity", "t12"."way", "t12"."customer0" AS "customer", "t12"."email" AS "customer_email", "obligation1"."id" AS "obligation_id", "obligation1"."due", "obligation1"."state" AS "obligation_state"
                                        FROM (SELECT "t11"."line_id", "t11"."request_number", "t11"."line_no", "t11"."item", "t11"."quantity", "t11"."unit_price", "t11"."reason", "t11"."requested_resolution", "t11"."requested_variant", "t11"."state", "t11"."way", "t11"."customer", "t11"."customer0", "t11"."order_number", "t11"."channel", "t11"."requested_date", "t11"."state0", "customer1"."customer_id", "customer1"."addr", "customer1"."cdemo", "customer1"."hdemo", "customer1"."birth_year", "customer1"."center", "customer1"."email"
                                                FROM (SELECT "return_request_line1"."line_id", "return_request_line1"."request_number", "return_request_line1"."line_no", "return_request_line1"."item", "return_request_line1"."quantity", "return_request_line1"."unit_price", "return_request_line1"."reason", "return_request_line1"."requested_resolution", "return_request_line1"."requested_variant", "return_request_line1"."state", "return_request_line1"."way", "return_request_line1"."customer", "return_request1"."customer" AS "customer0", "return_request1"."order_number", "return_request1"."channel", "return_request1"."requested_date", "return_request1"."state" AS "state0"
                                                        FROM "return_request_line" AS "return_request_line1"
                                                            INNER JOIN "return_request" AS "return_request1" ON "return_request_line1"."request_number" = "return_request1"."request_number") AS "t11"
                                                    LEFT JOIN "customer" AS "customer1" ON "t11"."customer" = "customer1"."sk") AS "t12"
                                            INNER JOIN "obligation" AS "obligation1" ON "obligation1"."entity" = 'return_request_line' AND "obligation1"."key" = CAST("t12"."line_id" AS VARCHAR) AND "obligation1"."kind" = 'inbound' AND "obligation1"."state" IN ('open', 'overdue', 'reopened')
                                        WHERE "t12"."state" = 'awaiting_goods') AS "t14"
                                    INNER JOIN "obligation" AS "obligation2" ON "t14"."obligation_id" = "obligation2"."id") AS "t15"
                            LEFT JOIN (SELECT "t21"."_ttrp_a_n17_0" AS "_ttrp_k_n17_0__ttrp_a_n17_0", COUNT("t22"."_ttrp_d_n17_0") AS "_ttrp_n_n17_0"
                                FROM (SELECT "obligation4"."created_at" AS "_ttrp_a_n17_0"
                                        FROM (SELECT "t17"."line_id", "t17"."request_number", "t17"."item", "t17"."quantity", "t17"."way", "t17"."customer0" AS "customer", "t17"."email" AS "customer_email", "obligation3"."id" AS "obligation_id", "obligation3"."due", "obligation3"."state" AS "obligation_state"
                                                FROM (SELECT "t16"."line_id", "t16"."request_number", "t16"."line_no", "t16"."item", "t16"."quantity", "t16"."unit_price", "t16"."reason", "t16"."requested_resolution", "t16"."requested_variant", "t16"."state", "t16"."way", "t16"."customer", "t16"."customer0", "t16"."order_number", "t16"."channel", "t16"."requested_date", "t16"."state0", "customer2"."customer_id", "customer2"."addr", "customer2"."cdemo", "customer2"."hdemo", "customer2"."birth_year", "customer2"."center", "customer2"."email"
                                                        FROM (SELECT "return_request_line2"."line_id", "return_request_line2"."request_number", "return_request_line2"."line_no", "return_request_line2"."item", "return_request_line2"."quantity", "return_request_line2"."unit_price", "return_request_line2"."reason", "return_request_line2"."requested_resolution", "return_request_line2"."requested_variant", "return_request_line2"."state", "return_request_line2"."way", "return_request_line2"."customer", "return_request2"."customer" AS "customer0", "return_request2"."order_number", "return_request2"."channel", "return_request2"."requested_date", "return_request2"."state" AS "state0"
                                                                FROM "return_request_line" AS "return_request_line2"
                                                                    INNER JOIN "return_request" AS "return_request2" ON "return_request_line2"."request_number" = "return_request2"."request_number") AS "t16"
                                                            LEFT JOIN "customer" AS "customer2" ON "t16"."customer" = "customer2"."sk") AS "t17"
                                                    INNER JOIN "obligation" AS "obligation3" ON "obligation3"."entity" = 'return_request_line' AND "obligation3"."key" = CAST("t17"."line_id" AS VARCHAR) AND "obligation3"."kind" = 'inbound' AND "obligation3"."state" IN ('open', 'overdue', 'reopened')
                                                WHERE "t17"."state" = 'awaiting_goods') AS "t19"
                                            INNER JOIN "obligation" AS "obligation4" ON "t19"."obligation_id" = "obligation4"."id"
                                        GROUP BY "obligation4"."created_at") AS "t21"
                                    INNER JOIN (SELECT "cal_date" AS "_ttrp_d_n17_0"
                                        FROM "date_dim") AS "t22" ON "t21"."_ttrp_a_n17_0" < "t22"."_ttrp_d_n17_0" AND "t22"."_ttrp_d_n17_0" <= :as_of
                                GROUP BY "t21"."_ttrp_a_n17_0") AS "t24" ON "t15"."_ttrp_a_n17_0" = "t24"."_ttrp_k_n17_0__ttrp_a_n17_0") AS "t25" ON "t10"."line_id" = "t25"."line_id") AS "t26"
            LEFT JOIN (SELECT "t30"."line_id", COUNT("monitor_inbound_verdict"."run") AS "reminders"
                FROM (SELECT "t28"."line_id", "t28"."request_number", "t28"."item", "t28"."quantity", "t28"."way", "t28"."customer0" AS "customer", "t28"."email" AS "customer_email", "obligation5"."id" AS "obligation_id", "obligation5"."due", "obligation5"."state" AS "obligation_state"
                        FROM (SELECT "t27"."line_id", "t27"."request_number", "t27"."line_no", "t27"."item", "t27"."quantity", "t27"."unit_price", "t27"."reason", "t27"."requested_resolution", "t27"."requested_variant", "t27"."state", "t27"."way", "t27"."customer", "t27"."customer0", "t27"."order_number", "t27"."channel", "t27"."requested_date", "t27"."state0", "customer3"."customer_id", "customer3"."addr", "customer3"."cdemo", "customer3"."hdemo", "customer3"."birth_year", "customer3"."center", "customer3"."email"
                                FROM (SELECT "return_request_line3"."line_id", "return_request_line3"."request_number", "return_request_line3"."line_no", "return_request_line3"."item", "return_request_line3"."quantity", "return_request_line3"."unit_price", "return_request_line3"."reason", "return_request_line3"."requested_resolution", "return_request_line3"."requested_variant", "return_request_line3"."state", "return_request_line3"."way", "return_request_line3"."customer", "return_request3"."customer" AS "customer0", "return_request3"."order_number", "return_request3"."channel", "return_request3"."requested_date", "return_request3"."state" AS "state0"
                                        FROM "return_request_line" AS "return_request_line3"
                                            INNER JOIN "return_request" AS "return_request3" ON "return_request_line3"."request_number" = "return_request3"."request_number") AS "t27"
                                    LEFT JOIN "customer" AS "customer3" ON "t27"."customer" = "customer3"."sk") AS "t28"
                            INNER JOIN "obligation" AS "obligation5" ON "obligation5"."entity" = 'return_request_line' AND "obligation5"."key" = CAST("t28"."line_id" AS VARCHAR) AND "obligation5"."kind" = 'inbound' AND "obligation5"."state" IN ('open', 'overdue', 'reopened')
                        WHERE "t28"."state" = 'awaiting_goods') AS "t30"
                    LEFT JOIN "monitor_inbound_verdict" ON "t30"."line_id" = "monitor_inbound_verdict"."line_id" AND "monitor_inbound_verdict"."route" = 'remind'
                GROUP BY "t30"."line_id") AS "t31" ON "t26"."line_id" = "t31"."line_id") AS "t32"
WHERE "t32"."route" = 'remind'
